def make_typed_dict(*, required_fields=None, optional_fields=None) ->type:
    if required_fields is None:
        required_fields = {}
    if optional_fields is None:
        optional_fields = {}
    required_td = TypedDict(DUMMY_REQUIRED_TYPED_DICT_NAME, required_fields)
    optional_td = TypedDict(DUMMY_OPTIONAL_TYPED_DICT_NAME, optional_fields, total=False)
    return TypedDict(DUMMY_TYPED_DICT_NAME, {
        'required_fields': required_td,
        'optional_fields': optional_td,
    })

def shrink_types(types, max_typed_dict_size):
    types = list(types)
    if not types:
        return Any
    typed_dicts = [t for t in types if is_anonymous_typed_dict(t)]
    non_typed_dicts = [t for t in types if not is_anonymous_typed_dict(t)]
    if typed_dicts and not non_typed_dicts:
        return shrink_typed_dict_types(typed_dicts, max_typed_dict_size)
    if typed_dicts and non_typed_dicts:
        shrunk_typed_dict = shrink_typed_dict_types(typed_dicts, max_typed_dict_size)
        non_typed_dicts.append(shrunk_typed_dict)
        types = non_typed_dicts
    else:
        types = non_typed_dicts
    unique = []
    for t in types:
        if not any(types_equal(t, u) for u in unique):
            unique.append(t)
    if len(unique) == 1:
        return unique[0]
    return Union[tuple(unique)]

def _rewrite_container(self, cls, container):
    if container.__module__ != "typing":
        return self.rewrite_malformed_container(container)
    args = getattr(container, "__args__", None)
    if args is None:
        return self.rewrite_malformed_container(container)
    elif args == ((),):
